def run(ctx):
    """把任务池按对目标的重要度重排——BabyAGI 的核心动作。"""
    pool = ctx.state.get('task_pool') or ctx.parse_json(ctx.text) or []
    if isinstance(pool, str):
        pool = [t for t in pool.splitlines() if t.strip()]
    if len(pool) > 1:
        ranked = ctx.llm(
            '目标是：' + str(ctx.state.get('objective', '')) +
            '\n任务列表：\n' + '\n'.join(f'- {t}' for t in pool) +
            '\n按对目标的重要度从高到低重排，只输出 JSON 数组。')
        ctx.state['task_pool'] = ctx.parse_json(ranked) or pool
    ctx.emit('prioritized', {'count': len(ctx.state['task_pool'])})
    return {'data': ctx.state['task_pool']}

